-- SQLite schema for the STANDALONE DEMO / automated tests only. Mirrors database/oracle exactly
-- (same table, column and constraint semantics). Production uses Oracle.
PRAGMA foreign_keys = ON;

CREATE TABLE DM_COMPANY (COMPANY_ID INTEGER PRIMARY KEY, COMPANY_CODE TEXT NOT NULL UNIQUE, COMPANY_NAME TEXT NOT NULL, COMPANY_NAME_AR TEXT, BASE_CURRENCY TEXT NOT NULL);
CREATE TABLE DM_BRANCH (BRANCH_ID INTEGER PRIMARY KEY, COMPANY_ID INTEGER NOT NULL REFERENCES DM_COMPANY, BRANCH_CODE TEXT NOT NULL, BRANCH_NAME TEXT NOT NULL, BRANCH_NAME_AR TEXT, IS_ACTIVE TEXT NOT NULL DEFAULT 'Y', UNIQUE (COMPANY_ID, BRANCH_CODE));
CREATE TABLE DM_GL_ACCOUNT (GL_ACCOUNT_ID INTEGER PRIMARY KEY, COMPANY_ID INTEGER NOT NULL, GL_CODE TEXT NOT NULL, GL_NAME TEXT NOT NULL, GL_NAME_AR TEXT,
  ACCOUNT_TYPE TEXT NOT NULL, BUDGET_CATEGORY TEXT CHECK (BUDGET_CATEGORY IN ('SALES','DISCOUNT','RETURN','COGS','OPEX')), EXPENSE_GROUP TEXT,
  NORMAL_BALANCE TEXT NOT NULL CHECK (NORMAL_BALANCE IN ('D','C')), IS_POSTING TEXT NOT NULL DEFAULT 'Y', IS_ACTIVE TEXT NOT NULL DEFAULT 'Y',
  IS_VAT TEXT NOT NULL DEFAULT 'N', IS_INTERNAL_TRANSFER TEXT NOT NULL DEFAULT 'N', UNIQUE (COMPANY_ID, GL_CODE));
CREATE TABLE DM_FIN_PERIOD (COMPANY_ID INTEGER NOT NULL, FIN_YEAR INTEGER NOT NULL, PERIOD_NO INTEGER NOT NULL, PERIOD_NAME TEXT NOT NULL, START_DATE TEXT NOT NULL, END_DATE TEXT NOT NULL, PRIMARY KEY (COMPANY_ID, FIN_YEAR, PERIOD_NO));
CREATE TABLE DM_JV_HEADER (JV_ID INTEGER PRIMARY KEY, COMPANY_ID INTEGER NOT NULL, BRANCH_ID INTEGER NOT NULL REFERENCES DM_BRANCH, JV_NO TEXT NOT NULL, JV_DATE TEXT NOT NULL, JV_TYPE TEXT NOT NULL,
  STATUS TEXT NOT NULL CHECK (STATUS IN ('DRAFT','POSTED','REVERSED')), DESCRIPTION TEXT);
CREATE INDEX DM_JVH_DATE_IX ON DM_JV_HEADER (COMPANY_ID, JV_DATE, STATUS);
CREATE TABLE DM_JV_DETAILS (JV_ID INTEGER NOT NULL REFERENCES DM_JV_HEADER, LINE_NO INTEGER NOT NULL, GL_ACCOUNT_ID INTEGER NOT NULL REFERENCES DM_GL_ACCOUNT, BRANCH_ID INTEGER,
  DEBIT NUMERIC NOT NULL DEFAULT 0, CREDIT NUMERIC NOT NULL DEFAULT 0, NARRATION TEXT, PRIMARY KEY (JV_ID, LINE_NO));
CREATE INDEX DM_JVD_GL_IX ON DM_JV_DETAILS (GL_ACCOUNT_ID);
CREATE TABLE DM_USERS (USER_ID INTEGER PRIMARY KEY, USERNAME TEXT NOT NULL UNIQUE, FULL_NAME TEXT NOT NULL, PASSWORD_HASH TEXT NOT NULL, ROLE_CODE TEXT NOT NULL, COMPANY_ID INTEGER NOT NULL, ALL_BRANCHES TEXT NOT NULL DEFAULT 'N', IS_ACTIVE TEXT NOT NULL DEFAULT 'Y');
CREATE TABLE DM_USER_BRANCH (USER_ID INTEGER NOT NULL, BRANCH_ID INTEGER NOT NULL, PRIMARY KEY (USER_ID, BRANCH_ID));

CREATE VIEW BX_COMPANY AS SELECT COMPANY_ID, COMPANY_CODE, COMPANY_NAME, COMPANY_NAME_AR, BASE_CURRENCY FROM DM_COMPANY;
CREATE VIEW BX_BRANCH AS SELECT BRANCH_ID, COMPANY_ID, BRANCH_CODE, BRANCH_NAME, BRANCH_NAME_AR, IS_ACTIVE FROM DM_BRANCH;
CREATE VIEW BX_GL_ACCOUNT AS SELECT GL_ACCOUNT_ID, COMPANY_ID, GL_CODE, GL_NAME, GL_NAME_AR, ACCOUNT_TYPE, BUDGET_CATEGORY, EXPENSE_GROUP, NORMAL_BALANCE, IS_POSTING, IS_ACTIVE, IS_VAT, IS_INTERNAL_TRANSFER FROM DM_GL_ACCOUNT;
CREATE VIEW BX_FIN_PERIOD AS SELECT COMPANY_ID, FIN_YEAR, PERIOD_NO, PERIOD_NAME, START_DATE, END_DATE FROM DM_FIN_PERIOD;
CREATE VIEW BX_JV_HEADER AS SELECT JV_ID, COMPANY_ID, BRANCH_ID, JV_NO, JV_DATE, JV_TYPE, STATUS, DESCRIPTION FROM DM_JV_HEADER;
CREATE VIEW BX_JV_DETAILS AS SELECT JV_ID, LINE_NO, GL_ACCOUNT_ID, BRANCH_ID, DEBIT, CREDIT, NARRATION FROM DM_JV_DETAILS;
CREATE VIEW BX_USERS AS SELECT USER_ID, USERNAME, FULL_NAME, PASSWORD_HASH, ROLE_CODE, COMPANY_ID, ALL_BRANCHES, IS_ACTIVE FROM DM_USERS;
CREATE VIEW BX_USER_BRANCH AS SELECT USER_ID, BRANCH_ID FROM DM_USER_BRANCH;

CREATE TABLE BUDGET_MASTER (
  BUDGET_ID INTEGER PRIMARY KEY AUTOINCREMENT, COMPANY_ID INTEGER NOT NULL, BUDGET_NO TEXT NOT NULL, BUDGET_NAME TEXT NOT NULL,
  BUDGET_TYPE TEXT NOT NULL DEFAULT 'OPERATING' CHECK (BUDGET_TYPE IN ('OPERATING')), FIN_YEAR INTEGER NOT NULL,
  START_DATE TEXT NOT NULL, END_DATE TEXT NOT NULL, CURRENCY_CODE TEXT NOT NULL,
  ALLOCATION_METHOD TEXT NOT NULL DEFAULT 'CALENDAR_DAYS' CHECK (ALLOCATION_METHOD IN ('CALENDAR_DAYS','WORKING_DAYS')),
  STATUS TEXT NOT NULL DEFAULT 'DRAFT' CHECK (STATUS IN ('DRAFT','SUBMITTED','APPROVED')),
  VERSION_NO INTEGER NOT NULL DEFAULT 0, REMARKS TEXT, ROW_VERSION INTEGER NOT NULL DEFAULT 1,
  SUBMITTED_BY TEXT, SUBMITTED_AT TEXT, APPROVED_BY TEXT, APPROVED_AT TEXT,
  CREATED_BY TEXT NOT NULL, CREATED_AT TEXT NOT NULL, UPDATED_BY TEXT, UPDATED_AT TEXT,
  CHECK (END_DATE > START_DATE), UNIQUE (COMPANY_ID, BUDGET_NO), UNIQUE (COMPANY_ID, FIN_YEAR, BUDGET_TYPE));
CREATE TABLE BUDGET_DETAILS (
  DETAIL_ID INTEGER PRIMARY KEY AUTOINCREMENT, BUDGET_ID INTEGER NOT NULL REFERENCES BUDGET_MASTER, BRANCH_ID INTEGER NOT NULL, GL_ACCOUNT_ID INTEGER NOT NULL,
  PERIOD_NO INTEGER NOT NULL CHECK (PERIOD_NO BETWEEN 1 AND 13), ORIGINAL_AMOUNT NUMERIC, CURRENT_AMOUNT NUMERIC NOT NULL DEFAULT 0,
  ROW_VERSION INTEGER NOT NULL DEFAULT 1, CREATED_BY TEXT NOT NULL, CREATED_AT TEXT NOT NULL, UPDATED_BY TEXT, UPDATED_AT TEXT,
  UNIQUE (BUDGET_ID, BRANCH_ID, GL_ACCOUNT_ID, PERIOD_NO));
CREATE TABLE BUDGET_APPROVAL_HISTORY (
  HISTORY_ID INTEGER PRIMARY KEY AUTOINCREMENT, BUDGET_ID INTEGER NOT NULL REFERENCES BUDGET_MASTER,
  ACTION TEXT NOT NULL CHECK (ACTION IN ('CREATE','UPDATE','SUBMIT','APPROVE','REJECT','REVISION_APPROVED','REVISION_REJECTED')),
  PREVIOUS_STATUS TEXT, NEW_STATUS TEXT NOT NULL, VERSION_NO INTEGER NOT NULL, ACTION_BY TEXT NOT NULL, ACTION_AT TEXT NOT NULL, REMARKS TEXT, REJECTION_REASON TEXT);
CREATE TABLE BUDGET_REVISION_HISTORY (
  REVISION_ID INTEGER PRIMARY KEY AUTOINCREMENT, BUDGET_ID INTEGER NOT NULL REFERENCES BUDGET_MASTER, DETAIL_ID INTEGER NOT NULL REFERENCES BUDGET_DETAILS,
  BRANCH_ID INTEGER NOT NULL, GL_ACCOUNT_ID INTEGER NOT NULL, PERIOD_NO INTEGER NOT NULL, BASE_VERSION_NO INTEGER NOT NULL, VERSION_NO INTEGER,
  ORIGINAL_AMOUNT NUMERIC NOT NULL, PREVIOUS_APPROVED_AMOUNT NUMERIC NOT NULL, REVISED_AMOUNT NUMERIC NOT NULL, DIFFERENCE_AMOUNT NUMERIC NOT NULL, DIFFERENCE_PCT NUMERIC,
  DETAIL_ROW_VERSION INTEGER NOT NULL, STATUS TEXT NOT NULL DEFAULT 'PENDING' CHECK (STATUS IN ('PENDING','APPROVED','REJECTED')),
  REASON TEXT NOT NULL, REJECTION_REASON TEXT, REVISED_BY TEXT NOT NULL, REVISED_AT TEXT NOT NULL, APPROVED_BY TEXT, APPROVED_AT TEXT);
CREATE TABLE BUDGET_ROLE_PERMISSION (ROLE_CODE TEXT NOT NULL, PERMISSION_CODE TEXT NOT NULL, PRIMARY KEY (ROLE_CODE, PERMISSION_CODE));
CREATE TABLE BUDGET_SETTINGS (SETTING_KEY TEXT PRIMARY KEY, SETTING_VALUE TEXT NOT NULL);
CREATE TABLE BUDGET_IDEMPOTENCY (IDEM_KEY TEXT PRIMARY KEY, USER_NAME TEXT NOT NULL, ENDPOINT TEXT NOT NULL, RESPONSE_JSON TEXT, CREATED_AT TEXT NOT NULL);

CREATE INDEX BD_BRANCH_IX ON BUDGET_DETAILS (BRANCH_ID, GL_ACCOUNT_ID);
CREATE INDEX BAH_BUDGET_IX ON BUDGET_APPROVAL_HISTORY (BUDGET_ID, ACTION_AT);
CREATE INDEX BRH_BUDGET_IX ON BUDGET_REVISION_HISTORY (BUDGET_ID, STATUS);

CREATE TRIGGER BAH_IMMUTABLE_UPD BEFORE UPDATE ON BUDGET_APPROVAL_HISTORY BEGIN SELECT RAISE(ABORT, 'BUDGET_APPROVAL_HISTORY is immutable'); END;
CREATE TRIGGER BAH_IMMUTABLE_DEL BEFORE DELETE ON BUDGET_APPROVAL_HISTORY BEGIN SELECT RAISE(ABORT, 'BUDGET_APPROVAL_HISTORY is immutable'); END;
CREATE TRIGGER BRH_IMMUTABLE_UPD BEFORE UPDATE ON BUDGET_REVISION_HISTORY
  WHEN OLD.STATUS <> 'PENDING' OR NEW.REVISED_AMOUNT <> OLD.REVISED_AMOUNT OR NEW.PREVIOUS_APPROVED_AMOUNT <> OLD.PREVIOUS_APPROVED_AMOUNT OR NEW.REVISED_BY <> OLD.REVISED_BY
  BEGIN SELECT RAISE(ABORT, 'BUDGET_REVISION_HISTORY row is immutable'); END;
CREATE TRIGGER BRH_IMMUTABLE_DEL BEFORE DELETE ON BUDGET_REVISION_HISTORY BEGIN SELECT RAISE(ABORT, 'BUDGET_REVISION_HISTORY row is immutable'); END;
CREATE TRIGGER BD_ORIGINAL_TRG BEFORE UPDATE OF ORIGINAL_AMOUNT ON BUDGET_DETAILS WHEN OLD.ORIGINAL_AMOUNT IS NOT NULL
  BEGIN SELECT RAISE(ABORT, 'ORIGINAL_AMOUNT is frozen after initial approval'); END;
